<?php use yii\helpers\Html; use yii\widgets\ActiveForm; $this->title='Input Nilai Sidang'; ?><div class="card form-card"><h2>📝 Input Nilai Sidang</h2><?php $f=ActiveForm::begin(); echo $f->field($model,'mahasiswa_id')->dropDownList(\yii\helpers\ArrayHelper::map($mahasiswa,'id',function($x){return $x->nim.' - '.$x->nama;}),['prompt'=>'Pilih Mahasiswa']); echo $f->field($model,'dosen_id')->dropDownList(\yii\helpers\ArrayHelper::map($dosen,'id','nama'),['prompt'=>'Pilih Dosen']); foreach($kriteria as $k):?><div class="score"><label><?=Html::encode($k->nama)?> (<?=$k->bobot?>%)</label><input name="score[<?=$k->id?>]" type="number" min="0" max="100" value="80" required></div><?php endforeach; echo $f->field($model,'tanggal')->input('date'); echo Html::submitButton('Simpan Nilai Sidang',['class'=>'btn blue full']); ActiveForm::end(); ?></div>
